export interface Query {
  /** query protocol */
  Protocol(request: QueryProtocol): Promise<QueryProtocolResponse>;
  DID(request: QueryDID): Promise<QueryDIDResponse>;
  DIDs(request: QueryDIDs): Promise<QueryDIDsResponse>;
  KYC(request: QueryKYC): Promise<QueryKYCResponse>;
  KYCs(request: QueryKYCs): Promise<QueryKYCsResponse>;
  SBT(request: QuerySBT): Promise<QuerySBTResponse>;
  SubAccountDid(request: QuerySubAccountDid): Promise<QuerySubAccountDidResponse>;
}

export const QueryServiceName = "metaearth.kyc.Query";
export class QueryClientImpl implements Query {
  private readonly rpc: Rpc;
  private readonly service: string;
  constructor(rpc: Rpc, opts?: { service?: string }) {
    this.service = opts?.service || QueryServiceName;
    this.rpc = rpc;
    this.Protocol = this.Protocol.bind(this);
    this.DID = this.DID.bind(this);
    this.DIDs = this.DIDs.bind(this);
    this.KYC = this.KYC.bind(this);
    this.KYCs = this.KYCs.bind(this);
    this.SBT = this.SBT.bind(this);
    this.SubAccountDid = this.SubAccountDid.bind(this);
  }
  Protocol(request: QueryProtocol): Promise<QueryProtocolResponse> {
    const data = QueryProtocol.encode(request).finish();
    const promise = this.rpc.request(this.service, "Protocol", data);
    return promise.then((data) => QueryProtocolResponse.decode(new BinaryReader(data)));
  }

  DID(request: QueryDID): Promise<QueryDIDResponse> {
    const data = QueryDID.encode(request).finish();
    const promise = this.rpc.request(this.service, "DID", data);
    return promise.then((data) => QueryDIDResponse.decode(new BinaryReader(data)));
  }

  DIDs(request: QueryDIDs): Promise<QueryDIDsResponse> {
    const data = QueryDIDs.encode(request).finish();
    const promise = this.rpc.request(this.service, "DIDs", data);
    return promise.then((data) => QueryDIDsResponse.decode(new BinaryReader(data)));
  }

  KYC(request: QueryKYC): Promise<QueryKYCResponse> {
    const data = QueryKYC.encode(request).finish();
    const promise = this.rpc.request(this.service, "KYC", data);
    return promise.then((data) => QueryKYCResponse.decode(new BinaryReader(data)));
  }

  KYCs(request: QueryKYCs): Promise<QueryKYCsResponse> {
    const data = QueryKYCs.encode(request).finish();
    const promise = this.rpc.request(this.service, "KYCs", data);
    return promise.then((data) => QueryKYCsResponse.decode(new BinaryReader(data)));
  }

  SBT(request: QuerySBT): Promise<QuerySBTResponse> {
    const data = QuerySBT.encode(request).finish();
    const promise = this.rpc.request(this.service, "SBT", data);
    return promise.then((data) => QuerySBTResponse.decode(new BinaryReader(data)));
  }

  SubAccountDid(request: QuerySubAccountDid): Promise<QuerySubAccountDidResponse> {
    const data = QuerySubAccountDid.encode(request).finish();
    const promise = this.rpc.request(this.service, "SubAccountDid", data);
    return promise.then((data) => QuerySubAccountDidResponse.decode(new BinaryReader(data)));
  }
}

interface Rpc {
  request(service: string, method: string, data: Uint8Array): Promise<Uint8Array>;
}

type Builtin = Date | Function | Uint8Array | string | number | boolean | undefined;

export type DeepPartial<T> = T extends Builtin ? T
  : T extends globalThis.Array<infer U> ? globalThis.Array<DeepPartial<U>>
  : T extends ReadonlyArray<infer U> ? ReadonlyArray<DeepPartial<U>>
  : T extends {} ? { [K in keyof T]?: DeepPartial<T[K]> }
  : Partial<T>;

type KeysOfUnion<T> = T extends T ? keyof T : never;
export type Exact<P, I extends P> = P extends Builtin ? P
  : P & { [K in keyof P]: Exact<P[K], I[K]> } & { [K in Exclude<keyof I, KeysOfUnion<P>>]: never };

function isSet(value: any): boolean {
  return value !== null && value !== undefined;
}

export interface MessageFns<T> {
  encode(message: T, writer?: BinaryWriter): BinaryWriter;
  decode(input: BinaryReader | Uint8Array, length?: number): T;
  fromJSON(object: any): T;
  toJSON(message: T): unknown;
  create<I extends Exact<DeepPartial<T>, I>>(base?: I): T;
  fromPartial<I extends Exact<DeepPartial<T>, I>>(object: I): T;
}
